import{_ as a,o as e,c as o,a2 as l}from"./chunks/framework.ifFCyy4k.js";const b=JSON.parse('{"title":"K2 量化與記憶體需求估算","description":"","frontmatter":{},"headers":[],"relativePath":"know/k2-quantization.md","filePath":"know/k2-quantization.md","lastUpdated":1793016282000}'),d={name:"know/k2-quantization.md"};function r(i,t,n,h,c,s){return e(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="k2-量化與記憶體需求估算" tabindex="-1">K2 量化與記憶體需求估算 <a class="header-anchor" href="#k2-量化與記憶體需求估算" aria-label="Permalink to &quot;K2 量化與記憶體需求估算&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-26</li><li>待查證: 4 位元量化的實際位元數與品質損失依格式與模型而異, 本章只給估算方法, 不給單一數字; 範例數字為假設架構的算術結果, 非特定模型</li></ul></div><p><strong>結論</strong>: 模型需要的記憶體約等於「權重大小 + 上下文暫存 (KV cache) + 執行開銷」, 三項都能事先估算. 權重大小是「參數量 x 每個參數的位元數 ÷ 8」; 實際下載前, 以模型頁面標示的檔案大小為準 (信心: 高, 屬算術, 開銷比例屬推論).</p><h2 id="k2-1-量化-用較低精度換取較小的記憶體占用" tabindex="-1">K2.1 量化: 用較低精度換取較小的記憶體占用 <a class="header-anchor" href="#k2-1-量化-用較低精度換取較小的記憶體占用" aria-label="Permalink to &quot;K2.1 量化: 用較低精度換取較小的記憶體占用&quot;">​</a></h2><p>量化 (quantization) 是把權重從 16 位元降到 8, 6, 5 或 4 位元等較低精度的做法. 位元數越低, 檔案與記憶體占用越小, 速度通常也更快, 但品質損失越大 (信心: 高).</p><table tabindex="0"><thead><tr><th>精度</th><th>每個參數約占</th><th>8B 參數模型的權重 (標稱)</th></tr></thead><tbody><tr><td>16 位元</td><td>2 位元組</td><td>約 16GB</td></tr><tr><td>8 位元</td><td>1 位元組</td><td>約 8GB</td></tr><tr><td>4 位元</td><td>0.5 位元組</td><td>約 4GB</td></tr></tbody></table><p>上表為算術結果 (80 億參數 x 位元組數), 用來示範估算, 非特定模型的實測值. 實際的 4 位元格式因為還存放縮放係數等資料, 檔案通常略大於標稱值 (推論, 信心: 中), 請以下載頁顯示的檔案大小為準.</p><p><strong>品質損失怎麼判斷</strong>: 損失程度因模型與任務而異, 公開評測多半只涵蓋特定基準, 不能代表自己的任務. 較可靠的做法是對同一個模型的兩個量化等級, 各跑一次 <a href="/lanai-handbook/build/m6-observability">M6</a>的測試集, 再選擇「品質夠用的最小檔案」(信心: 中高).</p><h3 id="檔案格式" tabindex="-1">檔案格式 <a class="header-anchor" href="#檔案格式" aria-label="Permalink to &quot;檔案格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>說明</th></tr></thead><tbody><tr><td>GGUF</td><td>llama.cpp 體系使用的單一檔案格式, 量化版本常以此發布</td></tr><tr><td>safetensors</td><td>權重常見的發布格式, 避免了 pickle 檔可能夾帶程式碼的風險 (見 <a href="/lanai-handbook/build/m1-inference">M1.5 節</a>)</td></tr></tbody></table><p>Ollama 匯入 GGUF 時不會自動量化; 若要自行量化, 須先用 llama.cpp 的 <code>llama-quantize</code> 等工具處理 (來源: Ollama 文件 Import).</p><h2 id="k2-2-估算步驟" tabindex="-1">K2.2 估算步驟 <a class="header-anchor" href="#k2-2-估算步驟" aria-label="Permalink to &quot;K2.2 估算步驟&quot;">​</a></h2><ol><li><strong>取得權重大小</strong>: 優先看模型下載頁的檔案大小. 沒有時用「參數量 x 每個參數位元數 ÷ 8」估算.</li><li><strong>加上 KV cache</strong>: 見 5.3 節.</li><li><strong>加上執行開銷</strong>: 推論引擎本身, 作業系統與介面都需要記憶體. 開銷沒有公開標準, 建議保守規劃, 例如讓總需求不超過可用記憶體的八成 (信心: 低, 屬推論).</li><li><strong>對照可用記憶體</strong>: 獨立顯示卡看顯示記憶體; Apple Silicon 看統一記憶體, 但作業系統與其他程式共用同一池.</li></ol><table tabindex="0"><thead><tr><th>情況</th><th>結果</th></tr></thead><tbody><tr><td>全部放得進顯示記憶體</td><td>速度最佳</td></tr><tr><td>放不下, 部分放到系統記憶體</td><td>能執行, 但速度明顯變慢 (信心: 高)</td></tr><tr><td>連系統記憶體也不足</td><td>載入失敗或系統嚴重卡頓; 請換較小的模型或較低的量化</td></tr></tbody></table><p><strong>混合專家模型 (MoE)</strong>: 名稱如「30B-A3B」表示總參數約 300 億, 每次推論啟用約 30 億. 記憶體要放下全部權重, 速度則接近較小的模型 (信心: 中高). 估算記憶體時請用總參數.</p><h2 id="k2-3-上下文長度與-kv-cache" tabindex="-1">K2.3 上下文長度與 KV cache <a class="header-anchor" href="#k2-3-上下文長度與-kv-cache" aria-label="Permalink to &quot;K2.3 上下文長度與 KV cache&quot;">​</a></h2><p>模型在對話過程中, 會把已處理的內容暫存為 KV cache. 上下文越長, 占用越大, 且與長度成正比.</p><p><strong>估算公式</strong> (信心: 高, 屬算術):</p><p>KV cache 位元組數 ≈ 2 x 層數 x KV 頭數 x 每頭維度 x 上下文長度 x 每個元素的位元組數</p><p><strong>範例</strong> (假設架構, 非特定模型): 32 層, 8 個 KV 頭, 每頭 128 維, 上下文 8,192, 16 位元 (2 位元組):</p><p>2 x 32 x 8 x 128 x 8,192 x 2 = 1,073,741,824 位元組, 約 1GiB.</p><p>實際模型的層數與頭數, 請從模型卡或設定檔取得.</p><h3 id="ollama-的相關設定" tabindex="-1">Ollama 的相關設定 <a class="header-anchor" href="#ollama-的相關設定" aria-label="Permalink to &quot;Ollama 的相關設定&quot;">​</a></h3><ul><li>預設上下文依顯示記憶體而定: 小於 24GiB 為 4k, 24 至 48GiB 為 32k, 48GiB 以上為 256k; 可用環境變數 <code>OLLAMA_CONTEXT_LENGTH</code> 調整 (來源: Ollama 文件 Context length).</li><li>同時處理的請求數 <code>OLLAMA_NUM_PARALLEL</code> 預設為 1; 所需記憶體會隨 <code>OLLAMA_NUM_PARALLEL</code> x <code>OLLAMA_CONTEXT_LENGTH</code> 增加 (來源: Ollama FAQ).</li></ul><p>因此記憶體吃緊時, 優先調降上下文長度與同時請求數, 再考慮換更小的模型. 設定方式見 <a href="/lanai-handbook/build/m1-inference">M1.8 節</a>.</p>',25)])])}const k=a(d,[["render",r]]);export{b as __pageData,k as default};
